# mask_studio — generated by tools/gen_model_py.py from the yaml
# cascade (2026-09-02 flip), then hand-edited since. The
# class IS the unit: family head → variants → quant cells;
# merged_defaults() walks the cascade. Parity pinned by
# tests/walls/suites/test_python_models.py + the http goldens.
#
# SSOT law: this file REPLACES model.yaml + variants/. A
# model.yaml reappearing next to it is a LOUD refusal.


from melite_models import  KnobRow,Model, Variant, Cell, LoraRow, Studio, SourceRow, LaneInputs, Provision, Genre, Quant


class MaskStudio(Model):
    id = 'mask-studio'
    genre = Genre.IMAGE
    label = 'Mask'
    description = 'Selection-only mask card: RT-DETR proposes, SAM3 refines → named class masks for inpaint flows.'
    engine = 'comfyui'
    card = 'mask-studio'
    studio = Studio(tenant='image/mask_studio', owns_params=True,
                    writes=('input_image', 'detect_mode', 'detection_threshold',
                            'sam_threshold', 'sam_dilation', 'output_mode',
                            'sam3_prompt', 'export_boxes', 'export_face',
                            'export_hands', 'export_body', 'export_paint',
                            'paint_mask', 'instance_filter', 'max_instances',
                            'outputs', 'roi'))
    form = 'form_mask_studio'
    source = SourceRow(repo_id='facebook/sam-vit-base')
    # The lane's loaders: SAM3 rides a CHECKPOINT (sam3.1 multiplex —
    # CheckpointLoaderSimple feeds SAM3_Detect's MODEL), RT-DETR rides a
    # diffusion_models UNET (UNETLoader feeds RTDETR_detect's MODEL). Two
    # loaders, both native core (comfy_extras) — no extension pack.
    lane_inputs = LaneInputs(
        checkpoint='sam3.1_multiplex_fp16.safetensors',
        unet='rt_detr_v4-x-hgnet_fp32.safetensors',
    )
    # The RT-DETR detector weights (Comfy-Org/SDPose — the same rows the
    # upstream sdpose workflow template names). The sam3.1 checkpoint is
    # on this deployment's disk already; its provision row lands when the
    # upstream url is pinned for audit.
    provisions = (
        Provision(folder='diffusion_models', name='rt_detr_v4-x-hgnet_fp32.safetensors', sha256='1ba4a7794c2f8b176327c887ba38fbe0f977049cbef149960288aa923d0239f3', url='https://huggingface.co/Comfy-Org/SDPose/resolve/main/diffusion_models/rt_detr_v4-x-hgnet_fp32.safetensors'),
    )
    defaults = dict(
            output_mode='segm',
            detect_mode='body',
            detection_threshold=0.35,
            sam_threshold=0.93,
            sam_dilation=0,
            export_face=False,
            export_hands=False,
            export_body=False,
            export_paint=False,
            sam3_prompt=None,
            export_boxes=True,
            instance_filter='all',
            max_instances=0,
            outputs='[]',
        )
    # the CASCADE GATE (image-edit rework 2026-09-05) — this lane
    # ships a single ComfyUI UNETLoader configuration. The cell states
    # the TRUE quant tier the loader reads (no tier switch today); a
    # future second cell row lands as a real tier (the family grows).
    variants = (
        Variant(id='standard', label='Standard', route='mask-studio', cells=(
            Cell(quant=Quant.F32, label='F32', route='mask-studio', vram_peak_gb=12.0),
        )),
    )

    # the mask-studio card surface (row 3, 2026-09-06 — twelfth card
    # in the KnobRow migration, first COMPILE-CARD). Sixteen rows in
    # three tiers. DIRECT rows target nodes the bare-default render
    # builds (LoadImage + the RT-DETR manifest lane). COMPILE rows (empty inject) name wire knobs the voice
    # consumes without a node input — routing directives, export
    # switches, recipe text (splice skips them by construction).
    # GATED-INPUT rows (empty inject + named target) feed a node
    # input that builds ONLY under configuration — sam_threshold
    # (SAM3_Detect.0.threshold once a primary/export selection
    # exists; the bare-default graph builds no SAM3 lane),
    # sam_dilation (GrowMask.0.expand when nonzero) and paint_mask
    # (LoadImageMask.0.image when paint is involved). refine_iterations
    # is a lane-internal doc constant (not wire) — no row.
    card_knobs = (
        KnobRow(card='input_image', inject='LoadImage.0.image', kind='s'),
        KnobRow(card='detection_threshold', inject='RTDETR_detect.0.threshold', kind='n'),
        KnobRow(card='max_instances', inject='RTDETR_detect.0.max_detections', kind='n'),
        KnobRow(card='sam_threshold', inject='', kind='n'),
        KnobRow(card='detect_mode', inject='', kind='s'),
        KnobRow(card='output_mode', inject='', kind='s'),
        KnobRow(card='instance_filter', inject='', kind='s'),
        KnobRow(card='export_boxes', inject='', kind='b'),
        KnobRow(card='export_face', inject='', kind='b'),
        KnobRow(card='export_hands', inject='', kind='b'),
        KnobRow(card='export_body', inject='', kind='b'),
        KnobRow(card='export_paint', inject='', kind='b'),
        KnobRow(card='roi', inject='', kind='s'),
        KnobRow(card='outputs', inject='', kind='s'),
        KnobRow(card='sam_dilation', inject='', kind='n'),
        KnobRow(card='paint_mask', inject='', kind='s'),
    )

